# Lesson 2: opening. It continues lesson 1 from the option onwards.
SL.append(dict(id='s-title', title='פתיחה', kind='title', part=None, h='אופציות, שחקנים ושווקים', body='', cls='', kick=None))

S('s-recap', 'מה היה במפגש 1', 'תזכורת: מה היה במפגש 1',
  '<div class="row eq2 top"><div class="col">'
  + TABLES(['מושג', 'בקיצור'], [
      ['נגזר (Derivative)', 'חוזה ששוויו נגזר ממחיר נכס בסיס (Underlying)'],
      ['פרמיה (Premium)', 'המחיר שמשלמים היום על זכות, כמו שובר הטיסה'],
      ['חשיפה נטו (Net exposure)', 'הכנסות פחות הוצאות, באותו מטבע ומועד'],
      ['חוזה אקדמה (Forward)', 'מול בנק, מעבר לדלפק (OTC). Long מקבל $S_{T} − K$, Short מקבל $K − S_{T}$'],
      ['חוזה עתידי (Futures)', 'אותו רעיון בבורסה, עם התחשבנות יומית']]) + '</div><div class="col">'
  + BAND('dg', 'שאלת המפתח מהמפגש הקודם: קודם מחשבים חשיפה נטו, ורק אחר כך שוקלים חוזה. החוזה מוסיף ערך, מיותר או מסוכן לפי היחס בינו לבין החשיפה.', 6)
  + BAND('note', 'בחוזה אקדמה שני הצדדים מחויבים. היום נעבור לנגזר שבו רק צד אחד מחויב: אופציה (Option). כמו שובר הטיסה, הזכות עולה פרמיה.', 7)
  + MEME('cool', 'אני אחרי מפגש 1', 'יודע מה זה Long ו-Short, ולא מתבלבל', 8) + '</div></div>', kick='לפני שמתחילים · תזכורת')

S('s-recap2', 'תזכורת: הנוסחאות', 'תזכורת: חוזה אקדמה (Forward) בשתי נוסחאות',
  '<div class="row eq2 top"><div class="rl">'
  + RL(['<b>הסיפור ממפגש 1:</b> מיכל קנתה (Long) מרון חוזה אקדמה על חבית נפט. מחיר החוזה, $K$, הוא 100 דולר. בפקיעה מחיר החבית בשוק, $S_{T}$, הוא 110 דולר.',
        '<b>Long, מיכל:</b> קונה ב-$K$ מה ששווה $S_{T}$.', '=S_{T} − K = 110 − 100 = 10',
        '<b>Short, רון:</b> מוכר ב-$K$ מה ששווה $S_{T}$.', '=K − S_{T} = 100 − 110 = −10',
        '<b>סכום אפס:</b> מה שמיכל מרוויחה, רון מפסיד. אין פרמיה, ושניהם מחויבים.']) + '</div><div class="col">'
  + ST(7, '<div class="card"><b class="ct">במילים של אקסל</b><p class="lg">' + TX('מחיר בפקיעה בתא A5, מחיר החוזה בתא B1:') + '</p><p class="lg">' + TX('Long: ') + XL('=A5-¤B¤1') + '</p><p class="lg">' + TX('Short: ') + XL('=¤B¤1-A5') + '</p><p class="lg">' + TX('הקיבוע של B1 מאפשר לגרור את הנוסחה למטה.') + '</p></div>')
  + MEME('sweat', 'רון, ביום הפקיעה', 'כשהחבית עולה ל-110, והוא התחייב למכור ב-100', 8) + '</div></div>', kick='לפני שמתחילים · תזכורת')

_d = {'A1': 'כמות (דולר)', 'B1': 200000, 'A2': 'מחיר החוזה (K)', 'B2': 3.7, 'A4': 'שער בפקיעה', 'B4': 'תשלום לספק (ש״ח)', 'C4': 'תוצאת החוזה', 'D4': 'עלות נטו'}
_s = {}
for _i, _p in enumerate([3.5, 3.6, 3.7, 3.8, 3.9]):
    _r = 5 + _i; _d[f'A{_r}'] = _p; _s[f'B{_r}'] = f'=$B$1*A{_r}'; _s[f'C{_r}'] = f'=$B$1*(A{_r}-$B$2)'; _s[f'D{_r}'] = f'=B{_r}-C{_r}'
XLS('x-warm', 'חימום: יבואן ממפגש 1', 'חימום ממפגש 1: יבואן קונה (Long) חוזה אקדמה',
    'יבואן ישלם לספק 200,000 דולר בעוד שלושה חודשים. כדי לא להמר על השער, הוא קונה (Long) חוזה אקדמה (Forward) על 200,000 דולר, במחיר חוזה (K) של 3.70 ש״ח לדולר. בנו את התשלום לספק בשקלים, את תוצאת החוזה ואת העלות נטו, בכל שער אפשרי בפקיעה.',
    _d, _s, [150, 160, 140, 130], [4], hints=['התשלום לספק בשקלים: הכמות בדולרים כפול השער בפקיעה.', 'תוצאת החוזה של Long: הכמות כפול (השער בפקיעה פחות מחיר החוזה).', 'העלות נטו: התשלום לספק פחות מה שהחוזה הרוויח. קבעו את B1 ואת B2 עם ¤.'],
    remind='תשלום = כמות × $S_{T}$. תוצאת Long = כמות × ($S_{T} − K$). עלות נטו = תשלום − תוצאה.', partial=['B5', 'C5', 'D5'],
    chart=CH(['A5', 'A9'], [dict(y=['B5', 'B9'], c='#8a93aa', lab='ללא חוזה'), dict(y=['D5', 'D9'], c=PNLC, lab='עלות נטו', dy=22)], 3.5, 3.9, 680000, 800000, [3.5, 3.6, 3.7, 3.8, 3.9], [680000, 720000, 760000, 800000], xl='שער בפקיעה', yl='ש״ח'),
    done='העלות נטו קבועה: 740,000 ש״ח, כלומר 200,000 כפול 3.70. זה כל הגידור.')

MCS('m-warm', 'חימום: שתי שאלות ממפגש 1', 'חימום ממפגש 1: שתי שאלות', [
    mc('qw1', 'לחברה הכנסות של 800,000 דולר והוצאות של 800,000 דולר, באותו חודש. הגזבר מציע לגדר את ההכנסות בחוזה אקדמה (Forward). מה נכון?', ['החוזה מיותר: החשיפה נטו אפס', 'החוזה מוסיף ערך: יש הכנסות בדולרים', 'חייבים לגדר גם את ההכנסות וגם את ההוצאות', 'החוזה מסוכן, כי הדולר תמיד עולה'], 0, 'הכנסות פחות הוצאות שוות אפס. הגידור הטבעי כבר עושה את העבודה.', rem='חשיפה נטו = הכנסות בדולרים − הוצאות בדולרים, באותו מועד.'),
    mc('qw2', 'מוכר (Short) בחוזה אקדמה על 1,000 חביות, במחיר חוזה (K) של 80 דולר. המחיר בפקיעה 74 דולר. מה התוצאה שלו?', ['רווח של 6,000 דולר', 'הפסד של 6,000 דולר', 'רווח של 74,000 דולר', 'אפס, כי לא שולמה פרמיה'], 0, '$1,000 × (80 − 74) = 6,000$. המוכר מרוויח כשהמחיר יורד.', rem='Short: כמות × ($K − S_{T}$).')])


ROUTE = [(1, 'אופציות ועסקת החלפה', 'Call ו-Put, ארבע פוזיציות, מכפיל ו-Swap', 'כ-55 דקות'),
         (2, 'השחקנים', 'מגדר (Hedger) וספקולנט (Speculator)', 'כ-20 דקות'),
         (3, 'היכן זה נסחר', 'שיקגו, תל אביב ושוק מעבר לדלפק', 'כ-15 דקות'),
         (4, 'מקרה בוחן: דלק סילוני', 'חברת תעופה, בתרגילי אקסל פשוטים', 'כ-20 דקות'),
         (5, 'תרגילים מסכמים למפגש 2', 'חישובים ואקסל, עם רמזים ופתרונות', 'כ-25 דקות'),
         (6, 'לבית', 'שאלות רב ברירה וקובץ תרגול', 'עבודה עצמית')]
S('s-route', 'מסלול המפגש', 'מסלול המפגש',
  '<p class="lead">' + TX('שאלה אחת מלווה את המפגש: מה ההבדל בין זכות לבין התחייבות, ומי משתמש בכל אחת.' + (' לחצו על חלק כדי לעבור אליו.' if MODE == 'deck' else '')) + '</p><div class="route r7">'
  + ''.join(rcard(n, t, d, m, f'p-{n}') for n, t, d, m in ROUTE) + '</div>'
  + BAND('note', 'קריאה למפגש: Hull, פרק 1 (מהדורה 11), החלקים על אופציות ועל סוגי המשתתפים בשוק. הדקות הן הערכה.'), kick='לפני שמתחילים')
